export const orthoOnTheFly = {
  id: 'ortho.live',
  label: 'Ortho On-the-Fly',
  enabled: (panel) => panel.layers.some((layer) => layer.rpc),
  run(panel) {
    const layer = panel.active;
    if (!layer?.rpc) throw new Error('Ortho On-the-Fly needs an image with an RPC model');
    return panel.setDisplay({ kind: 'ortho', layer: layer.id });
  },
};
